  transition: all 0.3s ease;
}

.twikoo .el-button--primary:hover {
  background: #0056b3;
  transform: translateY(-1px);
}

/* 评论列表样式 */
.twikoo .twikoo-comments {
  margin-top: 20px;
}

/* 单条评论样式 */
