  background: white;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 12px;
  border-left: 4px solid #007bff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  transition: all 0.3s ease;
}

.twikoo .twikoo-comment:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
}

/* 评论头部信息 */
.twikoo .twikoo-comment .twikoo-comment-header {
  display: flex;
  align-items: center;
  margin-bottom: 8px;
}

/* 评论者昵称 */
.twikoo .twikoo-comment .twikoo-comment-name {
  font-weight: 600;
  color: #333;
  font-size: 14px;
  margin-right: 8px;
}

/* 评论时间 */
.twikoo .twikoo-comment .twikoo-comment-time {
  color: #999;
  font-size: 12px;
}

/* 评论内容 */
.twikoo .twikoo-comment .twikoo-comment-content {
  color: #333;
  font-size: 14px;
  line-height: 1.6;
  margin: 8px 0;
}

/* 评论操作按钮 */
.twikoo .twikoo-comment .twikoo-comment-actions {
  margin-top: 8px;
}

.twikoo .twikoo-comment .twikoo-comment-action {
  color: #666;
  font-size: 12px;
  margin-right: 16px;
  cursor: pointer;
  transition: color 0.3s ease;
}

.twikoo .twikoo-comment .twikoo-comment-action:hover {
  color: #007bff;
}

/* 回复样式 */
.twikoo .twikoo-comment .twikoo-comment-reply {
  background: #f8f9fa;
  border-radius: 6px;
  padding: 12px;
  margin-top: 8px;
  border-left: 3px solid #dee2e6;
}

/* 评论统计 */
.twikoo .twikoo-comment-count {
  color: #666;
  font-size: 14px;
  margin-bottom: 16px;
  text-align: center;
}

/* 加载更多按钮 */
.twikoo .twikoo-load-more {
  text-align: center;
